import pathlib

STOP_SENTINEL = pathlib.Path('/var/run/example-agent.stop')


def halt_requested() -> bool:
    """A stop_file on disk outlives this process, so the supervisor cannot undo it."""
    return STOP_SENTINEL.exists()

