import anthropic

from app.control import halt_requested

client = anthropic.Anthropic()


def main():
    while True:
        if halt_requested():
            sys.exit(0)
        reply = client.messages.create(
            model='claude-sonnet-4-5',
            max_tokens=2048,
            messages=[{'role': 'user', 'content': next_task()}],
        )
        act(reply)


